window.DOC_TXT=window.DOC_TXT||{};DOC_TXT["d07_prj33"]={"title": "Раздел ПД № 12 3664.1-РВВ", "pages": 43, "pagesTxt": ["[стр. 1]\nЗаказчик –\r\nПУБЛИЧНОЕ АКЦИОНЕРНОЕ ОБЩЕСТВО\r\n\"ГОРНО-МЕТАЛЛУРГИЧЕСКАЯ КОМПАНИЯ \r\n«НОРИЛЬСКИЙ НИКЕЛЬ»\"\r\nПООФ. НОФ. СТРОИТЕЛЬСТВО ТРЕТЬЕГО \r\nПОЛЯ ХВОСТОХРАНИЛИЩА «ЛЕБЯЖЬЕ»\r\nПРОЕКТНАЯ ДОКУМЕНТАЦИЯ\r\nРАЗДЕЛ 12 «ИНАЯ ДОКУМЕНТАЦИЯ, УСТАНОВЛЕННАЯ \r\nЗАКОНОДАТЕЛЬНЫМИ АКТАМИ РОССИЙСКОЙ ФЕДЕРАЦИИ»\r\nЧАСТЬ 4 «РАСЧЕТ ВЕРОЯТНОГО ВРЕДА, КОТОРЫЙ МОЖЕТ \r\nБЫТЬ ПРИЧИНЕН ЖИЗНИ, ЗДОРОВЬЮ ФИЗИЧЕСКИХ ЛИЦ,\r\nИМУЩЕСТВУ ФИЗИЧЕСКИХ И ЮРИДИЧЕСКИХ ЛИЦ \r\nВ РЕЗУЛЬТАТЕ АВАРИИ НА ОБЪЕКТАХ ХВОСТОВОГО \r\nХОЗЯЙСТВА»\r\n3664.1-РВВ\r\nТом 12.4", "[стр. 2]\nАкционерное общество\r\n«МЕХАНОБР ИНЖИНИРИНГ»\r\nЗаказчик – ПУБЛИЧНОЕ АКЦИОНЕРНОЕ ОБЩЕСТВО\r\n\"ГОРНО-МЕТАЛЛУРГИЧЕСКАЯ КОМПАНИЯ \r\n«НОРИЛЬСКИЙ НИКЕЛЬ»\"\r\nПООФ. НОФ. СТРОИТЕЛЬСТВО ТРЕТЬЕГО ПОЛЯ \r\nХВОСТОХРАНИЛИЩА «ЛЕБЯЖЬЕ»\r\nПРОЕКТНАЯ ДОКУМЕНТАЦИЯ\r\nРАЗДЕЛ 12 «ИНАЯ ДОКУМЕНТАЦИЯ, УСТАНОВЛЕННАЯ ЗАКОНОДАТЕЛЬНЫМИ \r\nАКТАМИ РОССИЙСКОЙ ФЕДЕРАЦИИ»\r\nЧАСТЬ 4. РАСЧЕТ ВЕРОЯТНОГО ВРЕДА, КОТОРЫЙ МОЖЕТ БЫТЬ ПРИЧИНЕН \r\nЖИЗНИ, ЗДОРОВЬЮ ФИЗИЧЕСКИХ ЛИЦ, ИМУЩЕСТВУ ФИЗИЧЕСКИХ\r\nИ ЮРИДИЧЕСКИХ ЛИЦ В РЕЗУЛЬТАТЕ АВАРИИ НА ОБЪЕКТАХ\r\nХВОСТОВОГО ХОЗЯЙСТВА\r\n3664.1-РВВ\r\nТом 12.4\r\nГенеральный директор Е.М. Шендерович\r\nГлавный инженер проекта А.Л. Успенский\r\nСанкт-Петербург\r\n2018", "[стр. 3]\n3664.1-РВВ 2\r\n3664.1-РВВ.С\r\nИзм. Кол. уч. Лист № док. Подп. Дата\r\nРазраб. Бабич\r\nСодержание тома\r\nСтадия Лист Листов\r\nП 1 1\r\nН. контр. Филатова\r\nГИП Успенский\r\nБахрова Т.Е. D:\\2020\\3664.1 Изм. № 216-20 от 05.2020\\Том 12.4 3664.1-РВВ\\02_Содержание тома.doc\r\nСОДЕРЖАНИЕ ТОМА\r\nОбозначение Наименование Примечание\r\n3664.1-РВВ Раздел 12 «Иная документация, \r\nустановленная законодательными актами \r\nРоссийской Федерации»\r\nЧасть 4. Расчет вероятного вреда, \r\nкоторый может быть причинен жизни, \r\nздоровью физических лиц, имуществу\r\nфизических и юридических лиц \r\nв результате аварии на объектах \r\nхвостового хозяйства на 40 листах\r\nВсего листов в томе 42", "[стр. 4]\n1 \r\nОБЩЕСТВО С ОГРАНИЧЕННОЙ ОТВЕТСТВЕННОСТЬЮ \r\n \"КОМФОРТПРОЕКТ\" \r\nСВИДЕТЕЛЬСТВО О ЧЛЕНСТВЕ В СРО АССОЦИАЦИЯ «ОБЪЕДИНЕНИЕ\r\nПРОЕКТИРОВЩИКОВ» №0413.04-2011-7810060931-П-31 \r\nРАСЧЕТ \r\nВЕРОЯТНОГО ВРЕДА, КОТОРЫЙ МОЖЕТ БЫТЬ \r\nПРИЧИНЕН ЖИЗНИ, ЗДОРОВЬЮ ФИЗИЧЕСКИХ ЛИЦ, \r\nИМУЩЕСТВУ ФИЗИЧЕСКИХ И ЮРИДИЧЕСКИХ ЛИЦ \r\nВ РЕЗУЛЬТАТЕ АВАРИИ НА ПРОЕКТИРУЕМЫХ \r\nГИДРОТЕХНИЧЕСКИХ СООРУЖЕНИЯХ \r\nТРЕТЬЕГО ПОЛЯ ХВОСТОХРАНИЛИЩА \r\n«ЛЕБЯЖЬЕ» \r\nГенеральный директор \r\nООО «Комфортпроект» \r\n_______________ Лаврентьева Т.В.\r\nСанкт-Петербург \r\n2018", "[стр. 5]\n2\r\nСписок принятых сокращений и обозначений\r\nГТС – гидротехническое сооружение;\r\nПМК – передвижная механизированная колонна;\r\nНБ – нижний бьеф;\r\nВБ – верхний бьеф;\r\nНС – насосная станция;\r\nНПУ – нормальный подпорный уровень;\r\nФПУ – форсированный подпорный уровень;\r\nУМО – уровень мертвого объема;\r\nКИА – контрольно-измерительная аппаратура;\r\nПБ – правила безопасности;\r\nПЛАС – план ликвидации аварийных ситуаций;\r\nПДС – предельно-допустимое состояние;\r\nПДК – предельно-допустимая концентрация;\r\nАСФ – аварийно-спасательное формирование;\r\nКЧС – комиссия по чрезвычайным ситуациям;", "[стр. 6]\n3 \r\nСПИСОК РАЗРАБОТЧИКОВ «РАСЧЕТА ВРЕДА» \r\n_________________________________________________________ Сапегин Д.С. \r\n_________________________________________________________ Николаев А.Ю.\r\nНаименование и реквизиты организаций, привлеченных владельцем ГТС к разработке\r\nдекларации безопасности: \r\nОбщество с ограниченной ответственностью «Комфортпроект» \r\nООО «Комфортпроект» \r\nИНН 7810060931 \r\nР/с 40702810917060008308 в филиале №7806 ВТБ 24 (ПАО) г. Санкт-Петербург \r\nБИК 044030811 \r\nк/с 30101810300000000811 \r\nОКПО 94602917 \r\nКПП 781001001 ОГРН 5067847005750 \r\nНаименование должности и фамилия руководителя организации: \r\nГенеральный директор: \r\nЛаврентьева Татьяна Владимировна \r\nЮридический адрес: \r\n196084, Российская Федерация, \r\nСанкт-Петербург, ул. Глеба Успенского, д. 3, лит. М, пом. 2Н \r\nТелефон: +7 (921) 595-24-64 \r\nE-mail: komfortproekt@mail.ru", "[стр. 7]\n4\r\nОГЛАВЛЕНИЕ\r\nВВЕДЕНИЕ..................................................................................................................................................... 5\r\n1. Нормативные ссылки ................................................................................................................................6\r\n2. Перечень рассмотренных документов....................................................................................................8\r\n3. Принятые допущения и порядок расчетов .............................................................................................8\r\n4. Расчет вреда ............................................................................................................................................ 10\r\nВЫВОДЫ...................................................................................................................................................... 17\r\nПриложение 1. Исходные данные для расчета вероятного вреда от аварии ГТС ..............................18\r\nПриложение 2. Основные сценарии аварий ГТС, принятые к Расчету вероятного \r\nвреда.............................................................................................................................................................. 21\r\nПриложение 3. Результаты расчетов параметров зон аварийного воздействия \r\nпри наиболее тяжелой и наиболее вероятной аварии ГТС.....................................................................34\r\nПриложение 4. Планы зон аварийного воздействия при наиболее тяжелой и \r\nнаиболее вероятной авариях ГТС в северном направлении.....................................................................37\r\nПриложение 4.1. План зоны аварийного воздействия при прорыве в южном \r\nнаправлении .................................................................................................................................................. 38\r\nПриложение 5. План ГТС............................................................................................................................ 39\r\nПриложение 6. Типовое поперечное сечение по ГТС, аварии которых приняты \r\nк расчету вероятного вреда ....................................................................................................................... 40", "[стр. 8]\n5\r\nВВЕДЕНИЕ\r\nСооружения проектируемые.\r\nЗаказчик проекта (организация, эксплуатирующая ГТС): Публичное акционерное общество\r\n«Горно-металлургическая компания ″Норильский никель″».\r\nНаименование должности и фамилия руководителя организации: \r\nДиректор ПООФ ЗФ ПАО «ГМК ″НН″» – А.С. Цымбал.\r\nПолный почтовый адрес организации:\r\nРоссия, 663302, Красноярский край, г. Норильск, пл. Гвардейская, д. 2.\r\nТелефон: (3919) 95-80-81.\r\nБанковские реквизиты:\r\nИНН/КПП 8401005730/245702001\r\nР/с 40702810375520110650\r\nВ Сибирском филиале ПАО «РОСБАНК» г. Красноярск\r\nК/с 30101810000000000388\r\nБИК 040407388\r\nСведения об организации, выполнившей расчет вероятного вреда: \r\nРасчет вероятного вреда выполнен специалистами ООО «Комфортпроект».\r\nЦелью данного расчета является определение величины финансового обеспечения \r\nриска гражданской ответственности владельца гидротехнического сооружения \r\nот возможных последствий аварии на данных объектах во исполнение Закона РФ №117-ФЗ \r\nот 21.07.97 г. (ст.12, 15, 16 и 17) и постановления Правительства РФ от 18.12.01 г. №876 \r\n«Об утверждении Правил определения величины финансового обеспечения гражданской \r\nответственности за вред, причиненный в результате аварии гидротехнического \r\nсооружения». \r\nРасчет выполнен в соответствии с требованиями Приказа от 18.05.2002 г. \r\n№243/150/270/68/89 МЧС, Минэнерго, МПР, Минтранса и ГГТН России «Об утверждении \r\nПорядка определения размера вреда, который может быть причинен жизни, здоровью \r\nфизических лиц, имуществу физических и юридических лиц в результате аварии \r\nгидротехнического сооружения». \r\nОбъектом расчета являются проектируемые гидротехнические сооружения третьего \r\nполя хвостохранилища «Лебяжье» ЗФ ПАО «ГМК «НН». Определение размера вреда \r\nпроводилось в соответствии с приказом Федеральной службы по экологическому, \r\nтехнологическому и атомному надзору от 29 марта 2016г. №120 «Об утверждении \r\nметодики определения размера вреда, который может быть причинен жизни, здоровью \r\nфизических лиц, имуществу физических и юридических лиц в результате аварии \r\nгидротехнических сооружений (за исключением судоходных и портовых гидротехнических \r\nсооружений)».\r\nДанная методика предназначена для определения размера вреда, который может быть \r\nпричинен жизни, здоровью физических лиц, имуществу физических и юридических лиц \r\nв результате аварий гидротехнических сооружений (далее – ГТС) собственниками ГТС или \r\nэксплуатирующими организациями (далее – владельцы ГТС), а также специализи￾рованными организациями, привлекаемыми владельцами ГТС, экспертными центрами, \r\nопределенными Федеральной службой по экологическому, технологическому и атомному \r\nнадзору для проведения экспертизы декларации безопасности ГТС.\r\nМетодика предназначена для определения размера вероятного вреда, оцениваемого \r\nна основании прогнозных событий (вероятных аварий ГТС), вероятность сценариев кото￾рых оценивается в декларации безопасности ГТС на основании методик по оценке рисков \r\nв вероятностной постановке.\r\nРасчет вреда проведен по состоянию на март 2018 г.", "[стр. 9]\n6\r\n1. Нормативные ссылки\r\n1. Федеральный закон «О безопасности гидротехнических сооружений» от 21.07.97 \r\n№117-ФЗ. \r\n2. Федеральный закон Российской Федерации от 27 июля 2010 г. №225-ФЗ \r\n«Об обязательном страховании гражданской ответственности владельца опасного \r\nобъекта за причинение вреда в результате аварии на опасном объекте».\r\n3. Федеральный закон «Об охране окружающей природной среды» от 10.02.02 №7-ФЗ. \r\n4. Постановление Правительства Российской Федерации от 06.11.98 №1303 \r\n«Об утверждении положения о декларировании безопасности гидротехнических\r\nсооружений».\r\n5. Постановление Правительства РФ от 21 мая 2007 г. №304 «О классификации \r\nчрезвычайных ситуаций природного и техногенного характера».\r\n6. Постановление Правительства Российской Федерации от 18.12.2001 г. №876. \r\n«Об утверждении правил определения величины финансового обеспечения \r\nгражданской ответственности за вред, причиненный в результате аварии \r\nгидротехнического сооружения». \r\n7. Постановление Правительства Российской Федерации от 13.10.2008 N 750 «О порядке \r\nвыделения бюджетных ассигнований из резервного фонда Правительства Российской \r\nФедерации по предупреждению и ликвидации чрезвычайных ситуаций и последствий \r\nстихийных бедствий»\r\n8. Постановление Правительства Российской Федерации от 13 сентября 2016г. №913 \r\n«О ставках платы за негативное воздействие на окружающую среду и дополни￾тельных коэффициентах»\r\n9. «Методика расчета зон затопления при гидродинамических авариях на хранилищах \r\nпроизводственных отходов химических предприятий» (РД 09-391-99). \r\n10. «Правила безопасности гидротехнических сооружений накопителей жидких \r\nпромышленных отходов» (ПБ 03-438-02), утверждены постановлением \r\nГосгортехнадзора России от 28.01.2002 №6, зарегистрированы Минюстом России \r\n16.04.2002 г., рег. №3372.\r\n11. Федеральный закон «О защите населения и территорий от чрезвычайных ситуаций \r\nприродного и техногенного характера» от 21.12.94 г. №68-ФЗ.\r\n12. Федеральный закон «Об обязательном социальном страховании от несчастных \r\nслучаев на производстве и профессиональных заболеваний» от 24.07.98 г. №125-ФЗ \r\n(с изменениями). \r\n13. Приказ Минприроды России от 15 декабря 2009 г. №413 \"Об утверждении \r\nАдминистративного регламента исполнения Федеральной службой по экологи￾ческому, технологическому и атомному надзору государственной функции \r\nпо осуществлению государственного контроля и надзора за соблюдением \r\nсобственниками гидротехнических сооружений и эксплуатирующими организациями \r\nнорм и правил безопасности гидротехнических сооружений (за исключением \r\nсудоходных гидротехнических сооружений, а также гидротехнических сооружений, \r\nполномочия по осуществлению надзора за которыми переданы органам местного \r\nсамоуправления)\"", "[стр. 10]\n7\r\n14. «Порядок определения размера вреда, который может быть причинен жизни, \r\nздоровью физических лиц, имуществу физических и юридических лиц в результате \r\nаварии гидротехнического сооружения», утвержден совместным приказом МЧС \r\nРоссии, Минэнерго России, МПР России, Минтранса России и Госгортехнадзора \r\nРоссии от 18.05.2002 №243/150/270/68/89, зарегистрированным Минюстом России \r\n03.06.2002 №3493. \r\n15. Приказ МЧС РФ №105 от 28 февраля 2003 г. «Об утверждении Требований \r\nпо предупреждению чрезвычайных ситуаций на потенциально опасных объектах и \r\nобъектах жизнеобеспечения».\r\n16. Приказ Федеральной службы по экологическому, технологическому и атомному \r\nнадзору от 29 марта 2016г. №120 «Об утверждении методики определения размера \r\nвреда, который может быть причинен жизни, здоровью физических лиц, имуществу \r\nфизических и юридических лиц в результате аварии гидротехнических сооружений \r\n(за исключением судоходных и портовых гидротехнических сооружений)».", "[стр. 11]\n8\r\n2. Перечень рассмотренных документов\r\nПри выполнении «Расчета вреда…», рассмотрена и проанализирована следующая \r\nдокументация:\r\n1. Декларация безопасности гидротехнических сооружений. Хвостохранилище. \r\n3664.1-ДБГ, изм.1. АО «Механобр Инжиниринг» 2018 г.\r\n2. ПООФ. НОФ. Строительство третьего поля хвостохранилища «Лебяжье». Отчетная \r\nтехническая документация по инженерным изысканиям. Технический отчет по ре￾зультатам инженерно-геодезических изысканий. №356656-ТГ-656. Том 1. \r\nООО «Норильскгеология», 2018 г.\r\n3. ПООФ. НОФ. Строительство третьего поля хвостохранилища «Лебяжье». Отчетная \r\nтехническая документация по инженерным изысканиям. Технический отчет по ре￾зультатам инженерно-геологических изысканий. №356664-ИГ-664, изм.2. Том 2. \r\nООО «Норильскгеология», 2018 г.\r\n4. ПООФ. НОФ. Строительство третьего поля хвостохранилища «Лебяжье». Отчетная \r\nтехническая документация по инженерным изысканиям для строительства. Шифр: Р￾ССХ-3. Технический отчет по инженерно-гидрометеорологическим изысканиям. \r\nГТП-2016-88-2355/16-01-СД, изм.1. НПО «Гидротехпроект», 2016 г.\r\n5. ПООФ. НОФ. Строительство третьего поля хвостохранилища «Лебяжье». Отчетная \r\nтехническая документация по инженерным изысканиям для строительства. Техниче￾ский отчет по результатам инженерно-экологических изысканий. Том 3. №0916-ИЭ. \r\nООО «Норильскгеология», 2018 г.\r\n3. Принятые допущения и порядок расчетов\r\nПри определении сценариев аварий ГТС и величины вероятного вреда не рассматри￾вались аварии ГТС, вызванные непреодолимой силой.\r\nНе подлежали рассмотрению аварии, вызванные умыслом и противоправными дей￾ствиями потерпевших или других лиц (за исключением владельца ГТС).\r\nРасчеты проводились для проектируемого ГТС.В проектной документации \r\nпредусматриваются технические решения по организации хвостохранилища,\r\nпредназначенного для складирования отвальных хвостов обогащения вкрапленных и \r\nмедистых руд на Норильской обогатительной фабрике с выходом хвостов 8,0 млн. тонн \r\nв год.\r\nМетодика применяется для оценки размера вероятного вреда в целом и для \r\nопределения отдельных составляющих этого вреда.\r\nПорядок расчетов\r\nСогласно требованиям «Порядка определения размера вреда…» основные составляю￾щие ущерба от аварий ГТС определяются на базе прогнозов следующих показателей:\r\n− количества людей, которые могут погибнуть и пропасть без вести, кроме физических \r\nлиц, являющихся работниками ГТС, при исполнении ими служебных обязанностей \r\nна территории ГТС;\r\n− количества людей, которые могут быть травмированы и нуждаться в госпитализации, \r\nкроме физических лиц, являющихся работниками ГТС, при исполнении ими служеб￾ных обязанностей на территории ГТС;\r\n− количества работников ГТС, которые могут погибнуть и пропасть без вести при ис￾полнении ими служебных обязанностей на территории ГТС;", "[стр. 12]\n9\r\n− количества работников ГТС, которые при исполнении ими служебных обязанностей \r\nна территории ГТС могут быть травмированы и нуждаться в госпитализации;\r\n− ущерба основным и оборотным фондам предприятий, кроме основных и оборотных \r\nфондов владельца ГТС;\r\n− ущерба готовой продукции предприятий, кроме продукции владельца ГТС;\r\n− ущерба элементам транспорта и связи, жилому фонду, имуществу граждан, сельско￾хозяйственному производству, лесному фонду от потери леса как сырья по рыночным \r\nценам, затопления и гибели лесов, ущерба природной среде, а также ущерба, вызван￾ного нарушением водоснабжения из-за аварий водозаборных сооружений, ущерба \r\nобъектам водного транспорта и рыбному хозяйству;\r\n− расходов на ликвидацию последствий аварий ГТС.\r\nОбщая структура ущерба от аварий ГТС приведена в приложении №2\r\nк «Методике….».\r\nТаблица 1 Общая структура ущерба\r\nСоставляющая ущерба от аварий ГТС: Обозначение\r\nсоциальный ущерб Исоц\r\nущерб производственным фондам И1\r\nущерб готовой продукции предприятий И2\r\nущерб элементам транспорта и связи И3\r\nущерб жилому фонду и имуществу граждан И4\r\nрасходы на ликвидацию последствий аварии И5\r\nущерб сельскохозяйственному производству И6\r\nущерб лесному фонду от потери леса как сырья И7\r\nущерб, вызванный нарушением водоснабжения И8\r\nущерб объектам водного транспорта И9\r\nущерб рыбному хозяйству И10\r\nущерб природной среде И11\r\nпрочие виды ущерба И12\r\nКонкретный перечень основных составляющих ущерба, возможных в результате ава￾рий ГТС, для которого выполняется расчет вероятного вреда, разрабатывается на основе \r\nданной структуры по результатам анализа характера и величины опасных воздействий на \r\nжизнь и здоровье физических лиц, имущество физических и юридических лиц, природную \r\nсреду с учетом особенностей социально-экономических показателей развития территории, \r\nпопадающей в зону аварийного воздействия ГТС. Составляющие ущерба, невозможные при \r\nаварии конкретного ГТС, для которого выполняется расчет вероятного вреда, приравнива￾ются к нулю (п.53 Методики).", "[стр. 13]\n10\r\n4. Расчет вреда\r\n4.1 Социальный ущерб \r\nСоциальный ущерб определяется в соответствии с требованиями «Порядка….» исходя \r\nиз максимально возможного общего числа погибших и пострадавших при аварии ГТС лю￾дей суммированием следующих показателей:\r\nчисло погибших (безвозвратные потери NЛ11) и пострадавших (возвратные поте￾ри NЛ12) работников ГТС, которые при исполнении своих служебных обязанностей находи￾лись в зоне аварийного воздействия;\r\nчисло погибших (безвозвратные потери NЛ21) и пострадавших (возвратные поте￾ри NЛ22) людей среди населения постоянного проживания, находившегося на территориях, \r\nпопадающих в зоны аварийного воздействия;\r\nчисло погибших (безвозвратные потери NЛ31) и пострадавших (возвратные поте￾ри NЛ32) людей среди населения временного нахождения на территориях, попадающих \r\nв зоны аварийного воздействия.\r\nВеличина социального ущерба NЛ в натуральном выражении определяется \r\nпо формуле:\r\nNЛ = NЛ11 + NЛ21 + NЛ31 + NЛ12 + NЛ22 + NЛ32.\r\nПри оценке социального ущерба от аварии ГТС принимается, что: основной вклад \r\nв размер социального ущерба от аварии ГТС вносит возможный социальный ущерб в зоне \r\nзатопления, примыкающей к низовому откосу ограждающей дамбы ГТС; в верхнем бьефе \r\nГТС возвратные и безвозвратные потери людей не ожидаются.\r\nРельеф местности расположения хвостохранилища определяет, что в случае образова￾ния прорана в ограждающей дамбе поток прорыва по понижению рельефа уйдет по руслу \r\nручья Купец и далее по руслу реки Щучья в озеро Пясино. В зоне возможного затопления \r\nзданий, сооружений, населенных пунктов нет. В зоне действия поражающих факторов \r\nв случае гидродинамической аварии может до 3 человек из числа обслуживающего персо￾нала.\r\nВ соответствии с требованиями «Методики…» все работники ГТС, оказавшиеся в зоне \r\nзатопления, считаются попавшими в ближайшую к створу гидроузла зону катастрофиче￾ских разрушений. Общие потери среди работников ГТС принимаются равными 60% \r\nот численности персонала ГТС, находящегося в зоне катастрофических разрушений (2 че￾ловека); из них безвозвратные потери NЛ11 составят 40% от общих потерь. \r\nТогда, NЛ11 =1 человек; \r\nNЛ12 = 1человек.\r\nЧисло погибших (NЛ21) и пострадавших (NЛ22) среди населения постоянного прожи￾вания, находившегося на территориях, попадающих в зоны аварийного воздействия, опре￾деляется по среднестатистическим данным о субъекте Российской Федерации, на террито￾рии которого может произойти авария, если в зоне затопления отсутствуют городские и \r\nсельские поселения. В этом случае средняя плотность населения постоянного проживания \r\nPзз, которое может оказаться в зоне затопления (рекреации, транспортное сообщение, вре￾менные работы), принимается равной 5% от средней плотности населения субъекта Рос￾сийской Федерации Pсуб = Nсуб / Sсуб и рассчитывается по формуле:\r\nPзз = 0,05×Nсуб / Sсуб,\r\nгде: Nсуб– численность населения субъекта Российской Федерации, определяемая на год \r\nпроведения расчета размера вероятного вреда;\r\nПо исходным данным плотность населения Красноярского края на 2017 год составила \r\n1,21 чел. на 1 км2\r\n.\r\nНа основе этих данных (п.65 Методики) определяется общая численность населения \r\nпостоянного проживания в зоне возможного затопления, определенная по средней плотно￾сти населения субъекта Российской Федерации, равна:\r\nNзз = Pзз × Sзз,", "[стр. 14]\n11\r\nгде: Sзз– общая площадь зоны затопления при аварии ГТС, полученная по результатам рас￾четов волны прорыва. \r\nВ нашем случае постоянного проживающего населения в районе возможного затоп￾ления нет, плотность населения (Pзз) для Красноярского края составила 1,21 чел./км2\r\n.\r\nNЛ21+NЛ22= 0,05×2,5×1,5 ≈ 1\r\nТогда, NЛ21 = 0; NЛ22 = 1\r\nЧисло погибших (NЛ31) и пострадавших (NЛ32) среди населения временного нахожде￾ния на территориях, попадающих в зону затопления, оценивается при наличии предостав￾ленных администрациями муниципальных образований данных о численности населения \r\nвременного нахождения Niвр.нас., попадающего в зоны катастрофических, сильных, средних \r\nи слабых разрушений. К населению временного нахождения относятся:\r\n− отдыхающие санаториев, домов отдыха, детских лагерей, туристических баз;\r\n− сотрудники геологических партий, экологических служб;\r\n− кочующие пастухи, рыболовы, охотники, оленеводы.\r\nВ зоне катастрофических разрушений численность населения временного нахождения \r\nпринимается по данным, предоставленным администрациями муниципальных образований. \r\nВ отсутствие данных о характере и численности населения временного нахождения на тер￾ритории аварийного воздействия ГТС значения составляющих NЛ31 и NЛ32 принимаются \r\nравными нулю (п.74 Методики).\r\nСоциальный ущерб ИЛ11 персоналу ГТС, попадающему в зону затопления при аварии \r\nГТС, рассчитывается по формуле:\r\nИЛ1 = Ссв б/возвр× NЛ11 + К1 × Ссв возвр × NЛ12,\r\nгде: NЛ11– число погибших среди персонала ГТС;\r\nNЛ12– число пострадавших среди персонала ГТС;\r\nСсв – соответствующий предельный размер страховой выплаты;\r\nК1– степень вреда, причиненного здоровью пострадавших людей в зоне катастрофических \r\nразрушений, определяемая по пункту 76 Методики.\r\nВ соответствии с Правилами профессиональной деятельности страховщиков, ущерб за \r\nвред, причиненный жизни и здоровью одного пострадавшего (безвозвратная потеря) соста￾вит 2,0 млн. рублей, тогда \r\nИЛ1 = 2,0 × 1 + 0,9 × 2,0 ×1 = 3,8 млн. руб.\r\nИЛ2 = 0,3 × 2,0 × 1 = 0,6 млн. руб.\r\nСоциальный ущерб ИЛЗ населению временного нахождения равна 0.\r\nВеличина социального ущерба ИЛ в денежном выражении определяется путем сумми￾рования полученных значений денежного выражения социального ущерба персоналу ГТС, \r\nнаселению постоянного проживания и населению временного нахождения:\r\nИЛ = ИЛ1 + ИЛ2 + ИЛ3.\r\nтогда в нашем случае ИЛ = 4,4 млн. рублей для наиболее тяжелой и наиболее вероятной \r\nаварии.\r\n4.2 Имущественный ущерб \r\nИмущественный ущерб Иимущ. определяется по формуле:\r\nИимущ. = И1 + И2 + И3 + И4 + И5 + И6 + И7 + И8 + И9 + И10,\r\nгде: И1, И2, И3, И4, И5, И6, И7, И8, И9 и И10– соответствующие виды ущербов.\r\n1. Ущербы основным и оборотным фондам (И1,) – в рассматриваемом расчете равны \r\nнулю. Ущерб производственным фондам – т.к. в возможной зоне затопления предприятий и \r\nорганизаций нет И1, равен нулю. \r\nУчитывая параметры потока и высотные отметки местности, элементы транспорта и \r\nдругие объекты в зону затопления не попадают, кроме двух ниток магистрального газопро-", "[стр. 15]\n12\r\nвода, проходящих через реку Купец между створами №№ 1 и 2. При прорыве в северном \r\nнаправлении, в зону возможного затопления, также попадают 2 нитки магистрального газо￾провода, но при этом параметры потока прорыва будут больше, чем в случае прорыва в за￾падном или южном направлениях. Весь поток прорыва пойдет по пойме реки Купец. Пере￾ходы газопроводов через реку Купец проектировались с учетом возможного паводка 1% \r\nобеспеченности. Максимальный расчетный расход воды в проране при наиболее тяжелом \r\nразвитии аварийной ситуации меньше чем паводковый расход 1% обеспеченности на реке \r\nКупец, соответственно, можно принять, что в случае аварии, ущерб газопроводу нанесен не \r\nбудет.\r\n2. Ущерб готовой продукции предприятий (И2) – в рассматриваемом расчете равен \r\nнулю.\r\n3. Ущерб элементам транспорта и связи (И3) – в рассматриваемом расчете равен нулю, \r\n4. Ущерб жилому фонду и имуществу граждан (И4) –т.к. в зоне затопления население \r\nне проживает, в рассматриваемом расчете равен нулю.\r\n5. Расходы на ликвидацию последствий аварии (И5). Принимаются в размере 20% \r\nот ущербов п.п. 1-4, следовательно, в рассматриваемом случае равны нулю.\r\n6. Ущерб сельскохозяйственному производству (И6) – т.к. в зоне затопления отсут￾ствуют сельхозугодья, в рассматриваемом случае равен нулю.\r\n7. Ущербы лесному хозяйству (И7).\r\nУщерб лесному фонду от потери леса как сырья И7 следует определять по формуле:\r\n,\r\nгде: – доля утраченных земель лесного фонда, подверженных затоплению (принимается \r\n= 0,15);\r\nSлес древ – площадь земель лесного фонда в зоне аварийного воздействия, на которых ведется \r\nзаготовка древесины наиболее ценных пород, определяемая по формуле:\r\nSлес древ = Sзз сильн разр · kлес · kдрев,\r\nгде: Sзз сильн разр – площадь зоны сильных разрушений земель лесного фонда, определяемая \r\nпо критериям: глубина затопления H >3 м, скорость потока V> 2 м/с;\r\nkлес – лесистость территории субъекта Российской Федерации;\r\nkдрев – процент территорий, занятых преобладающими товарными древесными породами \r\nв лесах субъекта Российской Федерации;\r\nСлес – осредненная ставка платы за единицу объема деловой древесины, определяемая \r\nс учетом преобладающих пород лесных насаждений лесотаксового района, попадающего \r\nв зону затопления, и расстояний вывозки; принимается с учетом индексации ставок на год \r\nпроведения расчета.\r\nВ зону возможного затопления земли лесного фонда, на которых ведется \r\nлесозаготовка, не попадают, аварийный поток прорыва пройдет по руслу и пойменной \r\nчасти рек Купец и Щучья. Соответствующий ущерб равен нулю.\r\n8. Ущерб, вызванный нарушением водоснабжения.\r\nУщерб И8, вызванный нарушением водоснабжения, рассчитывается по формуле:\r\nИ8 = СврVв(SАВ / Sсуб) · (tв / Тгод),\r\nгде:\r\nСвр – ставка платы за забор (изъятие) водных ресурсов из поверхностных водных объектов \r\n(Красноярского края246 руб. по договору водопользования, с коэффициентом 1,75 \r\nна 2018 г.);\r\nVв – объем использования свежей воды в субъекте Российской Федерации\r\n(по Красноярскому краю1713,94 млн. м3\r\n);\r\nSсуб – площадь территории субъекта Российской Федерации (площадь Красноярского края \r\nсоставляет 2339700 км2\r\n);\r\nSАВ – площадь зоны аварийного воздействия, рассчитанная по формуле:\r\nSАВ = Sзз + Sав вб,\r\nгде: Sзз – площадь зоны затопления (1,5 км2 и 1,0 км2\r\n);\r\nИ=72 лес лес древ тд β ⋅⋅ ⋅ СS М\r\n2 β\r\n2 β", "[стр. 16]\n13\r\nSав вб – площадь зоны аварийного воздействия в верхнем бьефе;\r\ntв – число дней, необходимых на восстановление водоснабжения, принимается равным \r\n25 дням;\r\nТгод – число дней в году расчета вероятного вреда.\r\nИ8 =32400,15 руб. (для наиболее тяжелой аварии)\r\nИ8 =21600,10 руб. (для наиболее вероятной аварии)\r\n9. Ущерб объектам водного транспорта. \r\nУщерб объектам водного транспорта И9 на водохранилище определяется в случае \r\nвнесения водохранилища в перечень водных объектов, использующихся в целях водного \r\nтранспорта, в нашем случае равен нулю.\r\n10. Ущерб рыбному хозяйству.\r\nУщерб рыбному хозяйству И10 определяется при условии ведения на водохранилище \r\nрыбного промысла, в нашем случае равен нулю.\r\n11.Ущерб природной среде.\r\nВероятный ущерб природной среде в результате аварии ГТС должен включать все ви￾ды вероятного ущерба компонентам природной среды, которые могут иметь место при за￾топлении территории, примыкающей к низовому откосу ограждающей дамбы, и негатив￾ных воздействиях в верхнем бьефе ГТС, характерных для аварий ГТС гидроузлов, водохра￾нилищ, накопителей жидких промышленных отходов.\r\nПри расчете вероятного вреда от аварий ГТС в качестве отдельной составляющей \r\nущерб атмосферному воздуху и почвам не рассматривается.\r\nУщерб водным биологическим ресурсам учитывается при оценке ущерба рыбному хо￾зяйству. Ущерб остальным объектам животного мира учитывается в прочих видах ущерба \r\nот аварии ГТС.\r\nОстальные составляющие ущерба компонентам природной среды, не поддающиеся \r\nоценке в связи с отсутствием методик прогнозирования количества объектов животного и \r\nрастительного мира, подлежащих уничтожению в результате вероятной аварии ГТС, также \r\nучитываются в прочих видах ущерба от аварии ГТС.\r\nУщерб природной среде И11 в результате аварии ГТС гидроузлов, дамб (плотин) во￾дохозяйственных объектов рассчитывается по основным составляющим по формуле:\r\nИ11 = Илес + Ивод,\r\nгде: Илес – ущерб от затопления лесов;\r\nИвод – ущерб от сброса загрязняющих веществ в природные воды.\r\nУщерб от затопления лесов Илес рассчитывается, если в зону затопления при аварии \r\nГТС попадают земли лесного фонда. Величина Илес определяется по формуле:\r\n,\r\nгде: – доля утраченных земель из затопленных (принимается равной 0,15);\r\n– доля земель лесного фонда в зоне затопления, подверженных нарушению, принимается \r\nравной 0,4;\r\nКнорм лес – средняя стоимость затрат по субъекту Российской Федерации на посадку лесных \r\nкультур с использованием посадочного материала с закрытой корневой системой;\r\nSлес зз – площадь земель лесного фонда, попадающих в зону затопления, определяется по \r\nформуле:\r\nSлес зз = Sзз kлес,\r\nгде: Sзз – площадь зоны затопления;\r\nkлес – лесистость территории субъекта Российской Федерации).\r\nВ нашем случае не определяется. Весь поток прорыва пройдет в основном по руслу и \r\nпойменной части рек Купец и Щучья. Пойменная часть рек заросла кустарником и заболо￾чена. При определенных характеристиках волны прорыва, каких-либо значимых размеров \r\nущерба от затопления лесов не произойдет.\r\nУщерб от сброса (выброса) опасных веществ (отходов шламонакопителей, шламохра￾нилищ, золошлакоотвалов, накопителей сточных вод) в результате аварии ГТС определяет￾И= лес 1 лес зз норм лес 2 αS⋅⋅ ⋅ К α\r\nα1\r\nα2", "[стр. 17]\n14\r\nся как сумма ущерба по компонентам природной среды:\r\nИ8 = Ив + Ип + Иг + Иоб,\r\nгде: Ив – ущерб, нанесенный поверхностным водам (водотокам, водоемам);\r\nИп – ущерб, нанесенный почвам, земле, недрам;\r\nИг – ущерб, нанесенный подземным (в том числе грунтовым) водам;\r\nИоб – ущерб, нанесенный природным и природно-антропогенным объектам, расти￾тельному, животному миру и иным организмам, прочим компонентам природной среды.\r\nПри расчете не учитывается, что часть вредных веществ из профильтровавшихся в \r\nгрунтовые воды стоков задержится в почве и грунтах.\r\nПри определении степени загрязнения почвы принимается, что вся масса вредных ве￾ществ из профильтровавшейся с поверхности жидкости остается в почвенном слое и рас￾пределяется равномерно по глубине слоя и площади затопления. При расчете не учитывает￾ся, что часть вредных веществ из профильтровавшихся стоков, не задерживаясь в почвен￾ном слое, попадает в грунтовые воды.\r\nПри определении параметров загрязнения поверхностных водоемов необходимо при￾нимать массу вредных веществ, содержащихся в вытекшей или профильтровавшейся из \r\nхранилища (накопителя) жидкости, равномерно распределенную:\r\nдля замкнутых поверхностных водоемов – по всему объему водоема;\r\nдля проточных поверхностных водоемов – по сечению водоема.\r\nУщерб, нанесенный поверхностным водам (Ив) и подземным водам (Иг), определяется \r\nисходя из массы поступающих в них загрязняющих веществ, как соответствующая плата за \r\nсброс загрязняющего вещества с учетом экологической ситуации по бассейнам рек и морей \r\nрегиона договора водопользования.\r\nУщерб, который может быть нанесен поверхностным и подземным водам, определя￾ется как размер платы за сверхлимитный сброс по формуле:\r\n,\r\nгде: i – вид ЗВ (i = 1, 2 .... n);\r\nПв – размер платы за сверхлимитный сброс загрязняющих веществ, руб.;\r\nМi = (Mi вод – Mi л вод) – фактическая масса сброса i-го загрязняющего вещества в природные \r\nводы, т;\r\nСi – норматив платы за сброс одной тонны i-го загрязняющего вещества в природные воды \r\nв пределах установленного лимита сброса;\r\nКэ – коэффициент, учитывающий экологические факторы (состояние водных объектов) по \r\nбассейнам морей и рек;\r\nКинд – коэффициент индексации платы за сбросы загрязняющих веществ в поверхностные и \r\nподземные водные объекты на год расчета вероятного вреда.\r\nУщерб, нанесенный поверхностным водам (Ив), определяется исходя из массы \r\nпоступающих в них загрязняющих веществ, как соответствующая плата за сброс \r\nзагрязняющих веществ, с учетом экологической ситуации в регионе и договора \r\nводопользования. \r\nРасчет вреда выполняется для проектируемого хвостохранилища. Химический состав \r\nводы в пруде накопителя носит прогнозный характер и будет уточнен после ввода \r\nхвостохранилища в эксплуатацию.\r\nПеречень загрязняющих веществ и их концентрации, которые могут попасть в водный \r\nобъект в результате аварии, представлены в таблице 2.\r\nИ И =П =5 М С К К в г в ( ) ⋅ ⋅⋅ ⋅ ∑( i i э инд )", "[стр. 18]\n15\r\nТаблица 2 \r\n№\r\nп/п\r\nНаименование химического \r\nэлемента\r\nКонцентрация\r\nмг/л\r\n1 2 3\r\n1 Кальций 0,7\r\n2 Магний 50\r\n3 Сульфат 3,8\r\n5 Тисульфат 0,6\r\n6 Ионы хлора 0,75\r\n7 Сухой остаток 8,5\r\n8 Взвешенные вещества 0,5\r\nУщерб от изменения качества воды оценивается как за сверхлимитный выброс путем \r\nумножения массы загрязняющих веществ, поступивших в водный объект, на базовые \r\nнормативы платы за сброс загрязняющих веществ в поверхностные и подземные водные \r\nобъекты в пределах установленных лимитов с применением коэффициента индексации, \r\nэкологической ситуации и повышающего коэффициента 5.\r\nКэ – коэффициент экологической ситуации и экологической значимости состояния \r\nводных объектов 1 (Прочие реки бассейнов морей Северного, Ледовитого и Тихого \r\nокеанов).\r\nВ соответствии с постановлением Правительства от 13 сентября 2016 г. N 913\r\n«О ставках платы за негативное воздействие на окружающую среду и дополнительных \r\nкоэффициентах» и признанием утративших силу нормативных документов, определяющих \r\nнормативы платы за сброс загрязняющих веществ и дополнительных коэффициентов, \r\nрасчет ущерба, который может быть нанесен поверхностным и подземным водам, \r\nопределяется как\r\nИв (Иг) = 5∑ (Mi × Сi × Ко)\r\nКо – дополнительный коэффициент.\r\nМасса сброшенного загрязняющего вещества определяется по формуле: \r\nМi = Qв × Сi\r\nгде:\r\nСi – концентрация i-го сброшенного загрязняющего вещества;\r\nQв – объем сброшенной воды, м3\r\n. Определяется при рассмотрении варианта развития \r\nаварийной ситуации.\r\nОбъем сброса при наиболее тяжелой аварии – 6580 тыс. м3\r\n, из них 5264тыс. м3 – вода из \r\nотстойника с содержанием твердых веществ в соотношении 5:1, и 1316тыс. м3 твердого. \r\nРезультаты расчета представлены в таблице 3.\r\nТаблица 3 Результаты расчетов для наиболее тяжелой аварии\r\nНазвание ве￾щества\r\nКонцен￾трация\r\nОбъем \r\nсбоса Кол-во Коэфф. В рай￾оне\r\nСтавка Величина \r\nущерба\r\nКальций 0,7 5264000 3,6848 1 1 3,2 11,79136\r\nМагний 50 5264000 263,2 1 1 14,9 3921,68\r\nСульфат 3,8 5264000 20,0032 1 1 6 120,0192\r\nТисульфат 0,6 5264000 3,1584 1 1 198,3 626,3107\r\nИоны хлора 0,75 5264000 3,948 1 1 14711,7 58081,79\r\nСухой остаток 8,5 5264000 44,744 1 1 0,5 22,372\r\nВзвешеные в-ва 0,5 5264000 2,632 1 1 977,2 2571,99\r\nКальций 0,7 5264000 3,6848 1 1 3,2 11,79136\r\nИтого 65355,96\r\nс повышающим коэффициентом 5 326779,8", "[стр. 19]\n16\r\nОбъем сброса при наиболее вероятной аварии – 2100 тыс. м3\r\n, из них 1680 тыс. м3 – вода \r\nиз отстойника с содержанием твердых веществ в соотношении 5:1, и 420 тыс. м3 твердого. \r\nРезультаты расчета представлены в таблице 4.\r\nТаблица 4 Результаты расчетов\r\nНазвание ве￾щества\r\nКонцен￾трация\r\nОбъем \r\nсбоса Кол-во Коэфф. В рай￾оне\r\nСтавка Величина \r\nущерба\r\nКальций 0,7 1680000 1,176 1 1 3,2 3,7632\r\nМагний 50 1680000 84 1 1 14,9 1251,6\r\nСульфат 3,8 1680000 6,384 1 1 6 38,304\r\nТисульфат 0,6 1680000 1,008 1 1 198,3 199,8864\r\nИоны хлора 0,75 1680000 1,26 1 1 14711,7 18536,74\r\nСухой остаток 8,5 1680000 14,28 1 1 0,5 7,14\r\nВзвешеные в-ва 0,5 1680000 0,84 1 1 977,2 820,848\r\nКальций 0,7 1680000 1,176 1 1 3,2 3,7632\r\nИтого 20858,28\r\nс повышающим коэффициентом 5 104291,4\r\nУщерб, нанесенный почвам (Ип) в результате несанкционированного размещения от￾ходов, определяется по формуле:\r\n,\r\nгде: \r\nПв– размер платы за сверхлимитное размещение отходов, руб.;\r\nМi– фактическая масса отхода i-го класса опасности, т;\r\nСi– базовый норматив платы за размещение отхода в зависимости от класса опасности, \r\nруб./т;\r\nКэ– коэффициент, учитывающий экологические факторы (состояние почвы) по территори￾ям экономических районов Российской Федерации;\r\nКинд– коэффициент индексации платы за размещение опасных отходов.\r\nС учетом постановлением Правительства от 13 сентября 2016 г. N 913\r\nИп =Ив = 5∑ (Mi × Сi × Ко)\r\nОбъем сброса твердого 1316000 м3\r\n(для наиболее тяжелой аварии) и 420000 (для \r\nнаиболее вероятной), плотность 1,6 т/м3\r\n; ставка по отходам V класса на 2017г. 1,1 руб. за \r\nтонну.\r\nИп = 11580 тыс. рублей (для наиболее тяжелой аварии)\r\nИп = 3696 тыс. рублей (для наиболее вероятной аварии)\r\n12. Прочие виды ущерба И12 следует принимать в размере 10% от суммы имуще￾ственного ущерба и ущерба природной среде:\r\nИ12 = 0,1 × (И1 + И2 + И3 + И4 + И5 + И6 + И7 + И8 + И9 + И10 + И11).\r\nИ12 = 1194,0 тыс. руб. (для наиболее тяжелой аварии)\r\nИ12 = 382,2 тыс. руб. (для наиболее вероятной аварии)\r\nОбщий ущерб Иобщ рассчитывается по формуле:\r\nИобщ = И1 + И2 + И3 + И4 + И5 + И6 + И7 + И8 + И9 + И10 + И11 + И12\r\nОбщий ущерб составил:13133,98 тысяч рублей (для наиболее тяжелой аварии)\r\n4204,1 тыс. рублей (для наиболее вероятной аварии)\r\nИ =П =5 М С К К п в ⋅ ⋅⋅ ⋅ ∑( i i э инд )", "[стр. 20]\n17\r\nВЫВОДЫ\r\nОбъектом рассмотрения являются гидротехнические сооружения проектируемого \r\nтретьего поля хвостохранилища «Лебяжье» ПООФ НОФ ПАО «ГМК «Норильский \r\nникель».\r\nВ соответствии с требованиями постановления Правительства РФ от 18.12.01 г. \r\n№876 для гидротехнических сооружений проектируемого хвостохранилища рассчитана\r\nвеличина финансового обеспечения ответственности, исходя из оцененного в рублях \r\nразмера максимального вреда, который может быть причинен жизни, здоровью физических \r\nлиц, имуществу физических и юридических лиц в результате аварии гидротехнического \r\nсооружения. При наличии у собственника гидротехнического сооружения двух и более \r\nгидротехнических сооружений величина финансового обеспечения ответственности \r\nопределяется исходя из наибольшего значения вероятного вреда, который может быть \r\nпричинен в результате аварии одного из гидротехнических сооружений.\r\nРазмер вероятного вреда, который может быть причинен жизни, здоровью физиче￾ских лиц, имуществу физических и юридических лиц в результате аварии ГТС, определяет￾ся в денежном выражении как сумма двух показателей – социального ущерба и общего \r\nущерба.\r\nРассчитанный размер социального ущерба в результате аварии на проектируемом \r\nхвостохранилища для наиболее тяжелой и наиболее вероятной аварии, составит 4,4 млн. \r\nрублей.\r\nРассчитанный размер общего ущерба составил 13,13млн. рублей для наиболее тяже￾лой аварии и 4,2 млн. рублей для наиболее вероятной. \r\nВ целом размер вероятного вреда составил 17,53млн. рублей для наиболее тяжелой \r\nаварии и 8,6 млн. рублей для наиболее вероятной.\r\nОбъем финансового обеспечения риска гражданской ответственности владельца ГТС \r\nот возможных последствий аварии на них, определен в соответствии с Федеральным зако￾ном Российской Федерации от 27 июля 2010 г. N 225-ФЗ «Об обязательном страховании \r\nгражданской ответственности владельца опасного объекта за причинение вреда в результа￾те аварии на опасном объекте» в размере 10 млн. рублей.", "[стр. 21]\n18\r\nПриложение 1. Исходные данные для расчета вероятного вреда от аварии ГТС\r\nПроектируемое хвостохранилище расположено на водосборной площади реки Купец. \r\nРека Купец является притоком р. Щучьей, впадающей в оз. Пясино. Река Купец протекает \r\nпо площадке строительства третьего поля хвостохранилища с юга на север. Общая \r\nпротяженность р. Купец – 24,7 км, водосборная площадь – 44,3 км². Створ южного участка \r\nограждающей дамбы хвостохранилища расположен на р. Купец на расстоянии 13,2 км от \r\nустья реки.\r\nВ проектной документации предусматривается выполнить отвод стока реки Купец и \r\nвременных водотоков (ручьев Безымянный №2 и №3) от южного борта хвостохранилища \r\nпо водоотводному каналу, прокладываемому по западному борту хвостохранилища, в реку \r\nКупец, протекающую со стороны северного борта хвостохранилища.\r\nГидротехнические сооружения проектируемого третьего поля хвостохранилища с \r\nпроектируемыми инженерными коммуникациями предназначены для транспортирования и \r\nскладирования отвальных хвостов Норильской обогатительной фабрики и организации \r\nоборотного водоснабжения без негативного воздействия сооружений третьего поля \r\nхвостохранилища на прилегающие территории.\r\nХвостохранилище предназначено для складирования отвальных хвостов обогащения \r\nвкрапленных и медистых руд на Норильской обогатительной фабрике с выходом хвостов \r\n8,0 млн. тонн в год.\r\nОтстойный пруд хвостохранилища предназначен для отстоя хвостовой пульпы и \r\nосветления воды в отстойном пруду.\r\nПлощадка третьего поля хвостохранилища расположена на расстоянии 4 км к северо￾западу от г. Норильск. Площадка строительства ограничена с северной и западной сторон \r\nтрассой газопроводов, с южной стороны – трассами действующих коммуникаций, \r\nавтомобильных дорог и железной дороги, постройками промышленного назначения, \r\nдействующим промотвалом №2, с восточной стороны – ограждающей дамбой \r\nдействующего хвостохранилища «Лебяжье».\r\nХвостохранилище расположено на водосборной площади р. Купец.\r\nПлощадь хвостохранилища по оси ограждающей первичной дамбы составляет 4,1 км².\r\nХвостохранилище в плане имеет вид неправильного многоугольника.\r\nПо технологии заполнения хвостохранилище является намывным, по рельефу –\r\nравнинным.\r\nРабота хвостохранилища предусматривается в замкнутом цикле.\r\nПервоначальная емкость хвостохранилища организуется ограждающей первичной \r\nдамбой с северной, южной и западной сторон. С восточной стороны ограждающей дамбой \r\nявляется западный участок ограждающей дамбы действующего хвостохранилища \r\n«Лебяжье».\r\nДальнейшее наращивание ограждающей дамбы производится путем \r\nпоследовательной отсыпки дамб обвалования из привозного грунта на намытый пляж и \r\nнамыва очередного яруса, с формированием низового откоса дамбы с проектной крутизной \r\nпо всему контуру хвостохранилища. Емкость хвостохранилища обеспечит укладку хвостов \r\nфабрики на расчетный срок заполнения хвостохранилища – 15 лет.\r\nДля организации оборотного водоснабжения с первого года эксплуатации в чаше \r\nхвостохранилища должен быть создан пруд с объемом воды не менее 2,5 млн. м³.\r\nПри замкнутом контуре хвостохранилища обеспечивается возможность соблюдения \r\n\"нулевого\" баланса воды в хвостохранилище без сброса технологических вод \r\nв естественные водоемы.\r\nПри плановом количестве складируемых хвостов 120 млн. тонн и коэффициенте \r\nзаполнения хвостохранилища, равном от 0,55 в первые годы эксплуатации до 0,9 \r\nна конечные годы расчетного срока заполнения, требуемый объем хвостохранилища при \r\nобъемной плотности намывных хвостовых отложений 1,6 т/м³ составит 93,75 млн. м³", "[стр. 22]\n19\r\n(округленно 94,0 млн. м³). Проектная отметка заполнения хвостохранилища в соответствии \r\nс кривой объемов и площадей принимается равной 60,5 м (Б.С.). Отметка гребня \r\nограждающей дамбы на конец расчетного срока заполнения хвостохранилища (отметка \r\nгребня последней поярусной дамбы обвалования) в соответствии с п. 8.18 ПБ 03-438-02 \r\nсоставит 61,0 м (Б.С.)\r\nОсновные параметры хвостохранилища на начальный период и на конец \r\nрасчетного срока заполнения приведены в таблице\r\nТаблица 1.1 Основные характеристики хвостохранилища\r\nНаименование Ед. изм.\r\nПараметры\r\nНачальный период \r\nзаполнения\r\nКонец расчетного \r\nсрока заполнения хво￾стохранилища \r\nОтметка гребня \r\nограждающей дамбы м 43,0-44,0; 47,0\r\n(гребень первичной дамбы) 61,0\r\nПлощадь хвостохранилища \r\nна отметке гребня дамбы\r\n(по внутренней бровке)\r\nмлн. м² 4,02 4,05\r\nЕмкость хвостохранилища \r\nна отметке гребня дамбы\r\n(по внутренней бровке)\r\nмлн. м³ 20,68 94,0\r\nДлина ограждающей дамбы м 6105,0 7889,0\r\nМаксимальная высота \r\nограждающей дамбы м 10,0 28,0\r\n Первичная дамба с отм. 47,0 – участок дамбы по южному борту хвостохранилища\r\nПервичная ограждающая дамба – однородная земляная дамба распластанного \r\nпрофиля.\r\nОсновные параметры дамбы:\r\n• протяженность – 6105 м;\r\n• отметка гребня – 43,0-47,0 м (в Балтийской системе высот);\r\n• ширина по гребню – 18,0 м;\r\n• максимальная высота – 10,0 м;\r\n• средняя высота – 5,6 м;\r\n• крутизна верхового откоса – 1:2,5.\r\n• крутизна низового откоса – 1:1,5.\r\nШирина дамбы по гребню 18,0 м принята из условия отсыпки дамбы большегрузным \r\nавтотранспортом, прокладки распределительного пульповода, установки мачт освещения, \r\nустановки контрольно-измерительной аппаратуры (КИА) и автопроезда для их монтажа и \r\nобслуживания и строительства поярусных дамб обвалования.\r\nПо длине дамбы через каждые 2 км предусматриваются въезды на дамбу и съезды к \r\nподошве низового откоса дамбы.\r\nОграждающую дамбу предлагается отсыпать из скального грунта.\r\nНа верховом откосе дамбы предусматривается устройство противофильтрационного \r\nэкрана из гидромата 3DM-A-1,5 (Арктик) СТО 56910145-005-2011 с подстилающим слоем из \r\nсуглинистого грунта (хвосты НОФ). \r\nВ качестве понура предусматривается проложить гидромат 3DM-A-1,5 (Арктик) от \r\nподошвы верхового откоса ограждающей дамбы в сторону хвостохранилища на ширину \r\nоснования ограждающей дамбы как противофильтрационный элемент и армирующий \r\nэлемент для сооружения «ограждающая дамба – основание».\r\nДля компенсации и стабилизации возможных осадок, деформации дамбы, просадок \r\nоснования и снижения расчетных удельных нагрузок в основании дамбы преду-", "[стр. 23]\n20\r\nсматривается устройство скальной подушки. Скальная подушка отсыпается на высоту 2,0 м \r\nиз скального грунта, втопленного в грунт основания на глубину 0,5-1,0 м с Купл = 0,95.\r\nСо стороны низового откоса первичной дамбы, предусматривается устройство авто￾проезда из скального грунта для обслуживания ЛЭП 6 кВ. Ширина земляного полотна ав￾топроезда – 12,0 м, высота переменная – не менее 1,7 м.\r\nОграждающая дамба формируется в процессе эксплуатации отсыпкой дамб \r\nобвалования на намытые хвостовые отложения. Дамбы обвалования отсыпаются из \r\nскального грунта с устройством на верховом откосе дамб экрана из суглинистого грунта \r\n(хвостов НОФ). Ширина дамб по гребню 10 м, крутизна верхового и низового откосов −\r\n1:2, 1,5, соответственно, высота 3,0 м\r\nМаксимальная высота ограждающей дамбы на конец расчетного срока заполнения \r\nхвостохранилища составит 28,0 м, что соответствует II классу ГТС.\r\nКоэффициент запаса устойчивости ограждающей дамбы соответствует значению \r\nнормативного коэффициента устойчивости для дамб II класса.\r\nТаблица 1.2 Основные параметры хвостохранилища на конец расчетного срока заполнения\r\n№ \r\nп/п Наименование Ед. изм. Значение\r\n1 Проектная отметка заполнения хвостохранилища м 60,5\r\n2 Емкость хвостохранилища на проектной отметке заполнения млн. м³ 94,0\r\n3 Количество уложенных хвостов за расчетный срок заполнения \r\nхвостохранилища (15 лет) млн. т 120\r\n4 Расчетный коэффициент заполнения хвостохранилища 0,8\r\n5\r\nПлощадь хвостохранилища по линии верховой бровки гребня \r\nпоследней дамбы обвалования (на конец срока заполнения \r\nхвостохранилища) \r\nкм² 4,05\r\n6 Общая площадь хвостохранилища с учетом сооружений по \r\nотводу стока реки Купец и проектируемых коммуникаций км² 4,97\r\n7 Отметка гребня ограждающей дамбы на конец расчетного срока \r\nзаполнения хвостохранилища (15 лет) м 61,0\r\n8 Максимальная высота ограждающей дамбы на конец \r\nрасчетного срока заполнения хвостохранилища \r\nм 28,5\r\n9 Длина ограждающей дамбы на конец расчетного срока срока \r\nзаполнения хвостохранилища \r\nм 7889,0\r\n10 Ширина последней дамбы обвалования (№6) м 10,0\r\n11 Крутизна низового откоса ограждающей дамбы м 1:5\r\n12 Минимальная длина надводного пляжа м 100,0\r\n13 Максимальная отметка воды в отстойном пруду м 59,0\r\n14\r\nМинимальный перепад между отметкой надводного пляжа у \r\nверхового откоса последней дамбы обвалования (гребня \r\nограждающей дамбы) и уровнем воды в отстойном пруду\r\nм 1,5\r\n15 Класс гидротехнического сооружения на конец эксплуатации II\r\nКанал отвода стока р. Купец проложен по западному борту хвостохранилища. Сток р. \r\nКупец, притекающий к южному борту хвостохранилища, по водоотводному каналу \r\nпоступает в русло р. Купец, протекающей по северному борту канала. Канал рассчитан на \r\nпропуск паводковых вод 1% обеспеченности расходом 52,8 м³/сек. Основные параметры \r\nканала: протяженность – 4,119 км; ширина по дну – 4,0 м; крутизна откосов – 1:2; средняя \r\nглубина выемки под каналом – 6,0 м; максимальная глубина выемки под каналом – 10 м.", "[стр. 24]\n21\r\nПриложение 2. Основные сценарии аварий ГТС, принятые к Расчету \r\nвероятного вреда\r\nПеречень основных возможных сценариев аварий ГТС и их негативных воздействий \r\nопределяется составом ГТС и особенностями их работы.\r\nМетодика определения размера вреда рекомендует опасности, способные иницииро￾вать аварии ГТС, подразделять на природные и техногенные, внешние и внутренние.\r\nПри проектировании хвостохранилища были проведены всесторонние исследования и \r\nучтены, в соответствии с требованиями нормативных документов, следующие опасности: \r\nприродные, техногенные, внешние и внутренние, которые способны инициировать аварии \r\nна ГТС, а также оценены возможные аварийные ситуации на гидротехнических \r\nсооружениях проектируемого хвостохранилища. \r\nК техногенным опасностям аварий ГТС следует относить взрывы, пожары на про￾мышленных объектах, расположенных в районе ГТС, крупные аварии на проходящих \r\nв зоне влияния ГТС автомобильных или железнодорожных трассах, трубопроводах транс￾портировки природного газа, нефтепродуктов и других пожаро- и взрывоопасных веществ. \r\nКроме того, к техногенным опасностям аварий ГТС следует относить и опасности от ава￾рий, возможных на ГТС, расположенных в каскаде ГЭС выше и ниже анализируемого ГТС \r\n(комплекса ГТС). Таких объектов вблизи рассматриваемого хвостохранилища нет.\r\nРекомендуемый перечень типовых сценариев аварий ГТС для основных видов ГТС \r\nприведен в приложении №1 к Методике (таблица 2.1). Рекомендуемый перечень типовых \r\nсценариев аварии ГТС для основных видов ГТС не учитывает все возможные особенности \r\nконкретных ГТС.\r\nАварии ГТС, приводящие к возникновению ЧС на определенной территории и аквато￾рии, разделяются на две основные группы:\r\n− аварии ГТС без прорыва напорного фронта;\r\n− аварии ГТС с прорывом напорного фронта в результате образования прорана или бре￾ши.\r\nК авариям ГТС без прорыва напорного фронта, приводящим к возникновению ЧС \r\nна определенной территории и акватории, относятся (Методика):\r\n1)-постепенное переполнение хвостохранилища (накопителя) из-за превышения по￾ступающего расхода пропускной способности ГТС (например, при поступлении в водохра￾нилище или накопитель нерасчетного паводка, неполном открытии водосбросных отвер￾стий из-за поломок затворов или ошибок персонала);\r\n-возникновение в хвостохранилище чрезвычайно больших волн (например, волн вы￾теснения из-за оползня берега, селевого паводка, волны прорыва из вышележащих водо￾хранилищ, завальных озер или временных водоемов, под пруженных ледниками, волн от \r\nкрупных взрывов);\r\n-аварии ГТС, связанные с повреждением отдельных элементов сооружений – водово￾дов, механического оборудования водозаборных и водосбросных сооружений.\r\n2) Для плотин и ограждающих дамб накопителей жидких промышленных отходов \r\nследует рассматривать сценарии нарушения фильтрационного режима из-за суффозии ма￾териала плотины (дамбы) или основания, образования трещин, разгерметизации противо￾фильтрационных элементов. При приближении фильтрационных вод к поверхности возни￾кает подтопление местности, которое учитывается при оценке ущерба.\r\n3) К авариям ГТС с прорывом напорного фронта в результате образования прорана \r\nили бреши, приводящим к возникновению ЧС на определенной территории и акватории, \r\nотносятся:\r\n– образование прорана в сооружениях из грунтовых материалов (плотины, дамбы ка￾налов, ограждающие дамбы хранилищ отходов) или бреши в бетонных или железобетон￾ных сооружениях без аварийного повышения уровня воды со стороны верхнего бьефа гид￾роузла (уровня воды в хранилище опасных отходов, сточных вод);", "[стр. 25]\n22\r\n– образование прорана в сооружениях из грунтовых материалов или бреши в бетон￾ных или железобетонных сооружениях при аварийном повышении уровня воды со стороны \r\nверхнего бьефа;\r\n– образование прорана в сооружениях из грунтовых материалов – ограждающих дам￾бах накопителей жидких промышленных отходов (золошлакоотвалы, шламохранилища, \r\nхвостохранилища, гидроотвалы, накопители промышленных стоков).\r\nТаблица 2.1 Рекомендуемый перечень сценариев\r\nТип сценария аварии Вид ГТС Характерные признаки \r\nаварии ГТС\r\nНегативные воз￾действия аварии \r\nГТС\r\n1 2 3 4\r\nРазрушения напорного \r\nфронта, сопровожда￾ющиеся образованием \r\nпрорана, в который \r\nпроисходит излив воды \r\nили жидких отходов, \r\nнеконтролируемый \r\nперсоналом ГТС, а \r\nтакже неконтролируе￾мый перелив через \r\nгребень плотины из-за \r\nпереполнения водо￾хранилища или воз￾никновения экстре￾мальных волн\r\nПлотины водохра￾нилищ\r\nОбразование прорана в \r\nнапорном фронте\r\n1. Опорожнение \r\nводохранилища.\r\n2. Затопление \r\nместности\r\nПерелив через плотину \r\nбез прорыва напорного \r\nфронта (при переполне￾нии водохранилища, \r\nвозникновении в водо￾хранилище волн вытес￾нения или экстремаль￾ных ветровых волн)\r\nЗатопление мест￾ности\r\nЗдания гидроэлек￾тростанций\r\nПрорыв напорного \r\nфронта\r\n1. Опорожнение \r\nводохранилища.\r\n2. Затопление \r\nместности\r\nВодосбросные, во￾доспускные и водо￾выпускные соору￾жения\r\nПрорыв напорного \r\nфронта\r\n1. Опорожнение \r\nводохранилища.\r\n2. Затопление \r\nместности", "[стр. 26]\n23\r\n1 2 3 4\r\nРазрушения напорного \r\nфронта, сопровожда￾ющиеся образованием \r\nпрорана, в который \r\nпроисходит излив воды \r\nили жидких отходов, \r\nнеконтролируемый \r\nперсоналом ГТС, а \r\nтакже неконтролируе￾мый перелив через \r\nгребень плотины из-за \r\nпереполнения водо￾хранилища или воз￾никновения экстре￾мальных волн\r\nКаналы Прорыв напорного \r\nфронта насыпей (для \r\nканалов в насыпи или\r\nполунасыпи)\r\nЗатопление мест￾ности\r\nПерелив длинных волн \r\nчерез гребень насыпей \r\n(возможная ситуация \r\nпри резком закрытии \r\nзатворов и резких пере￾ключениях насосных \r\nстанций)\r\nЗатопление мест￾ности\r\nТуннели Нарушение оболочки Подтопление мест￾ности из-за избы￾точной фильтрации\r\nСооружения (дам￾бы), ограждающие \r\nхранилища жидких \r\nотходов промыш￾ленных организа￾ций\r\nПрорыв дамбы 1. Затопление \r\nместности.\r\n2. Вынос жидких \r\nотходов промыш￾ленных организа￾ций\r\nСооружения, пред￾назначенные для \r\nзащиты от навод￾нений, дамбы обва￾лования польдеров \r\nи осушенных тер￾риторий\r\nОбразование прорана в \r\nнапорном фронте\r\n1. Опорожнение \r\nводохранилища.\r\n2. Затопление \r\nместности\r\nПерелив через дамбу \r\nбез прорыва напорного \r\nфронта (при переполне￾нии водохранилища, \r\nвозникновении в водо￾хранилище волн вытес￾нения или экстремаль￾ных ветровых волн)\r\nЗатопление мест￾ности", "[стр. 27]\n24\r\n1 2 3 4\r\nПовреждения отдель￾ных элементов соору￾жения, приведшие к \r\nнеобходимости ава￾рийного понижения \r\nнапора на ГТС и со￾провождавшиеся сбро￾сом воды или жидких \r\nотходов\r\nПлотины водохра￾нилищ\r\nПовреждение плотины, \r\nсоздающее угрозу раз￾рушения напорного \r\nфронта с образованием \r\nпрорана\r\n1. Опорожнение \r\nводохранилища.\r\n2. Затопление \r\nместности\r\nЗдания гидроэлек￾тростанций\r\nПовреждение здания \r\nгидроэлектростанций, \r\nсоздающее угрозу гибе￾ли (травмирования) \r\nперсонала и (или) раз￾рушения напорного \r\nфронта с образованием \r\nпрорана\r\n1. Гибель (травми￾рование) персона￾ла.\r\n2. Опорожнение \r\nводохранилища.\r\n2.1. Затопление \r\nместности\r\nПовреждения отдель￾ных элементов соору￾жения, приведшие к \r\nнеобходимости ава￾рийного понижения \r\nнапора на ГТС и со￾провождавшиеся сбро￾сом воды или жидких \r\nотходов\r\nВодосбросные, во￾доспускные и водо￾выпускные соору￾жения\r\nПовреждение сооруже￾ния, создающее угрозу \r\nразрушения напорного \r\nфронта с образованием \r\nпрорана\r\n1. Опорожнение \r\nводохранилища.\r\n2. Затопление \r\nместности\r\nКаналы Повреждение насыпи \r\nканала, создающее \r\nугрозу разрушения \r\nнапорного фронта с об￾разованием прорана \r\n(для каналов в насыпи \r\nили полунасыпи)\r\nЗатопление мест￾ности\r\nТуннели Разрушение запорных \r\nустройств\r\nПрохождение по \r\nтуннелю в нижний \r\nбьеф нерасчетного \r\nрасхода воды (за￾топление местно￾сти, возможные \r\nдальнейшие раз￾рушения)\r\nАварии ГТС, золошла￾коотвалов и шламона￾копителей, содержа￾щих в отходах опасные \r\nвещества, связанные с \r\nнарушением фильтра￾ционной прочности \r\nГТС и его основания и \r\nприведшие к загрязне￾нию опасными веще￾ствами территории вне \r\nГТС\r\nСооружения (дам￾бы), ограждающие \r\nхранилища жидких \r\nотходов промыш￾ленных и сельско￾хозяйственных ор￾ганизаций\r\nНарушение режима \r\nфильтрации\r\nЗагрязнение терри￾тории, поверх￾ностных и грунто￾вых вод вредными \r\nвеществами", "[стр. 28]\n25\r\nРанжирование возможных сценариев аварий по уровню опасности для персонала, \r\nнаселения, имущества и окружающей природной среды показывает, что для \r\nрассматриваемого ГТС возможные аварийные ситуации без прорыва напорного фронта и \r\nаварийные ситуации, приводящие к подтоплению местности со стороны низового откоса \r\nограждающей дамбы из-за фильтрационных процессов, из дальнейшего рассмотрения \r\nможно исключить ввиду незначительных последствий для природной среды и \r\nпроживающего населения.\r\nУчитывая рекомендации, изложенные в Методике по возможным сценариям \r\nаварийной ситуации и особенности рассматриваемого ГТС, в качестве возможного \r\nсценария развития аварийной ситуации, следует принять сценарий «разрушения напорного \r\nфронта, сопровождающиеся образованием прорана, в который происходит излив воды, \r\nнеконтролируемый персоналом ГТС, а также неконтролируемый перелив через гребень \r\nдамбы из-за переполнения хвостохранилища или возникновения экстремальных волн».\r\nГидродинамическая авария на хвостохранилище может возникнуть при условии, \r\nесли ограждающая дамба утратит свое функциональное значение и перестанет удерживать \r\nот растекания находящиеся в чаше хвостохранилища хвосты и воду, или при разрыве \r\nраспределительных пульповодов с местным размывом низового откоса ограждающей \r\nдамбы.\r\nОсновная опасность при эксплуатации сооружений хвостохранилища связана с \r\nвозможностью возникновения аварий, которые могут возникнуть по следующим \r\nсценариям:\r\n1. Обрушение низового откоса ограждающей дамбы при потере статической \r\nустойчивости сооружения.\r\nПричины развития аварии: \r\n− не полный учет при проектировании особенностей инженерно-геологических \r\nусловий площадки хвостохранилища, а также некачественная подготовка его основания в \r\nстроительный период;\r\n− укладка некондиционных грунтов в тело ограждающей дамбы;\r\n− некачественное уплотнение материала тела ограждающей дамбы;\r\n− примыкание отстойного пруда к ограждающей дамбе;\r\n− превышение предельно допустимого уровня воды в отстойном пруду;\r\n− не соблюдение расчетного заложения низового откоса дамбы;\r\n− несоответствие фактических и расчетных физико-механических свойств хво￾стовых отложений;\r\n− превышение фактического положения кривой депрессии над проектным по￾ложением.\r\n2. Разрушение ограждающей дамбы из-за потери фильтрационной прочности \r\nтела и/или основания.\r\nПричины развития аварии: \r\n− укладка в тело дамбы некондиционного, отличного от проектного грунта, \r\nмерзлых грунтов;\r\n− некачественное уплотнение грунта тела дамбы при строительстве и подготов￾ка основания;\r\n− ошибки эксплуатации (отстойный пруд примыкает к дамбе).\r\n3. Разрушение ограждающей дамбы при переливе воды через ее гребень.\r\nПричины развития аварии: \r\n− нарушения в работе водоотводных сооружений (уменьшение пропускной \r\nспособности);\r\n− отказ оборудования насосной плавучей станции оборотной воды;\r\n− неконтролируемый подъем уровня воды отстойного пруда;\r\n− отметка воды в отстойном пруду выше предельно допустимой;", "[стр. 29]\n26\r\n− несоблюдения требований по длине пляжа и превышения минимальной от￾метки хвостов у верхового откоса дамбы над уровнем воды в пруде; \r\n− из-за стихийных бедствий (продолжительных ливней, сильного ветра, интенсив￾ного таяния снега и др.), ведущих к переполнению хвостохранилища.\r\n4. Местный размыв дамбы из-за аварии на распределительном пульповоде, про￾ложенном по гребню дамбы.\r\nПо трассам пульповодов и водоводов могут возникнуть аварийные ситуации при \r\nдеформации оснований (оползни, просадки), что приведет к порыву трубопроводов и \r\nрастеканию пульпы или воды из трубопроводов на окружающую поверхность земли. К \r\nразвитию аварийной ситуации также могут привести неисправность запорной арматуры, \r\nизнос стенок труб, перемораживание трубопроводов, коррозия, заиление пульповодов и \r\nобразование в них пробок, разрыв трубы в результате гидравлического удара при \r\nнеправильной эксплуатации или непредвиденных обстоятельствах.\r\nАнализ аварий выявил, что наиболее тяжелые последствия приносят аварии, \r\nсвязанные с переливом воды через гребень ограждающих дамб. При расчете возможных \r\nпоследствий аварий принято:\r\n– наиболее тяжёлая авария связана с переливом воды через ограждающую дамбу \r\nхвостохранилища, так как при этом в хвостохранилище будет накоплено максимальное \r\nколичество воды, а на дамбу будет воздействовать максимальный напор. Перелив воды \r\nчерез гребень ограждающей дамбы (образование прорана), может произойти вследствие \r\nразличных причин (указаны в сценариях). \r\n– наиболее вероятная авария связана с локальным разрушением (размывом) \r\nограждающей дамбы с захватом прудка\r\nБлок-схемы вероятных сценариев возникновения и развития гидродинамических \r\nаварий на ГТС хвостохранилища приведены на рис. 2.1 -2.2.", "[стр. 30]\n27\r\nРисунок 2.1 Блок-схема вероятных сценариев возникновения и развития \r\nгидродинамической аварии на ограждающей дамбе хвостохранилища\r\nПерелив воды через \r\nгребень дамбы, разрыв \r\nраспределительного \r\nпульповода\r\nПотеря устойчивости \r\nдамбы\r\nВынос частиц грунта с \r\nфильтрационной \r\nводой на низовом \r\nоткосе дамбы\r\nЧастичный размыв \r\nгребня дамбы\r\nОбрушение дамбы в \r\nвиде локального \r\nоползня\r\nОползание низового \r\nоткоса дамбы\r\nУвеличение ширины и \r\nглубины прорана\r\nФронтальное \r\nобрушение дамбы\r\nРастекание аварийного \r\nпотока, затопление \r\nприлегающей \r\nтерритории\r\nРисунок 2.2 Блок–схема анализа вероятных сценариев возникновения и развития \r\nаварийных ситуаций второго вида (локальные чрезвычайные ситуации)\r\nПлавучая насосная станция\r\nРазрушение плавучей насосной \r\nустановки и отводящего \r\nводовода\r\nОтключение электроэнергии\r\nПереход на аварийный режим или приостановка (остановка) фабрики\r\nРисунок 2.3 – Блок-схема анализа вероятных сценариев возникновения и развития \r\nаварийных ситуаций второго вида\r\nПульповоды \r\nи водовод оборотной воды\r\nПлавучая насосная \r\nстанция\r\nОтказ запорной \r\nарматуры\r\nРазрыв \r\nтрубопроводов\r\nОтказ запорной \r\nарматуры\r\nПереход на резервные сооружения, оборудование. Частичный излив пульпы.\r\nВозможна приостановка работы фабрики", "[стр. 31]\n28\r\nРассмотрены следующие сценарии развития аварийной ситуации.\r\nСценарий 1: обрушение низового откоса ограждающей дамбы при потере статической \r\nустойчивости сооружения. Сценарий 2: разрушение ограждающей дамбы из-за потери \r\nфильтрационной прочности тела и/или основания. Сценарий 3: разрушение ограждающей \r\nдамбы при переливе воды через ее гребень. Сценарий 4: местный размыв дамбы из-за \r\nаварии на распределительном пульповоде, проложенном по гребню дамбы.\r\nНа хвостохранилище возможны следующие сценарии развития гидродинамической \r\nаварии:\r\nСценарий №1. Обрушение низового откоса ограждающей дамбы при потере \r\nстатической устойчивости сооружения.\r\nПричины развития аварии: \r\n− неполный учет при проектировании особенностей инженерно-геологических \r\nусловий площадки хвостохранилища, а также некачественная подготовка его основания в \r\nстроительный период;\r\n− укладка некондиционных грунтов в тело ограждающей дамбы;\r\n− некачественное уплотнение материала тела ограждающей дамбы;\r\n− примыкание отстойного пруда к ограждающей дамбе;\r\n− превышение уровня воды в отстойном пруду предельно допустимого.\r\nСценарий №2. Разрушение ограждающей дамбы из-за потери фильтрационной \r\nпрочности тела и/или основания.\r\nПричины развития аварии: \r\n− укладка в тело дамбы некондиционного, отличного от проектного грунта, не￾качественное уплотнение материала;\r\n− плохое уплотнение грунтов дамбы и основания;\r\n− ошибки эксплуатации (отстойный пруд примыкает к дамбе).\r\nСценарий №3. Разрушение ограждающей дамбы при переливе воды через ее гребень.\r\nПричины развития аварии: \r\n− уменьшение пропускной способности ПлНС;\r\n− отказ оборудования насосной станции;\r\n− примыкание отстойного пруда к дамбе;\r\n− отметка воды в отстойном пруду выше предельно допустимой;\r\n− из-за стихийных бедствий (продолжительных ливней, сильного ветра, интен￾сивного таяния снега и др.), ведущих к переполнению хвостохранилища.\r\nСценарий №4. Местный размыв дамбы из-за аварии на распределительном \r\nпульповоде.\r\nПо трассам пульповодов и водоводов могут возникнуть аварийные ситуации при \r\nдеформации оснований (оползни, просадки), что приведет к порыву трубопроводов и \r\nрастеканию пульпы или воды из трубопроводов на окружающую поверхность земли. К \r\nразвитию аварийной ситуации также могут привести неисправность запорной арматуры, \r\nизнос стенок труб, перемораживание трубопроводов, коррозия, заиление пульповодов и \r\nобразование в них пробок, разрыв трубы в результате гидравлического удара при \r\nнеправильной эксплуатации или непредвиденных обстоятельствах.\r\nАвария, связанная с нарушением гидротранспорта, развивается сравнительно \r\nмедленно, что позволяет своевременно принять необходимые меры для их локализации и \r\nликвидации. Специфика и гидравлических условий (консистенции и напора) \r\nтранспортируемой пульпы не создаёт предпосылок для быстрого размыва гребня дамбы в \r\nслучае протечки. Кроме того, в вероятности подобного сценария должна быть учтена \r\nвероятность необнаружения протечки (минимальна при регламентном обходе). Таким \r\nобразом, вероятность подобного сценария, как произведения риска прорыва \r\nраспределительного пульповода и необнаружения протечки, которая приведет \r\nпервоначальному размыву дамбы до уровня прудка, оценивается величиной ниже 10-7\r\n1/год. \r\nДанный сценарий в настоящей работе не рассматривается вследствие его малой \r\nвероятности.", "[стр. 32]\n29\r\nОбразование прорана в теле дамбы накопителя\r\nРазрушение откоса дамбы накопителя переливающимся потоком Разрушение дамбы накопителя в результате внутренней эрозии \r\nПерелив воды через гребень из-за \r\nпереполнения прудка \r\nПерелив воды через гребень из-за \r\nобрушения откоса дамбы накопителя\r\nс захватом прудка или осадки\r\nгребня \r\nисключительное или\r\nПереполнение \r\nпруда при \r\nработающей \r\nплавучей НС, \r\nбереговой \r\nнасосной\r\nПереполнение \r\nпруда из-за \r\nотказа плавучей \r\nНС или \r\nбереговой \r\nнасосной\r\nОбрушение \r\nоткоса дамбы \r\nнакопителя с\r\nзахватом \r\nпрудка \r\nОсадка гребня \r\nдамбы \r\nнакопителя\r\nниже уровня \r\nводы в прудке \r\nнакопителя \r\nили\r\nРазвитие внутренней эрозии в \r\nтеле дамбы накопителя и/или в \r\nосновании \r\nРазвитие внутренней эрозии в \r\nтеле дамбы накопителя из-за \r\nобрушения откоса без захвата \r\nпруда \r\nМеханическая \r\nсуффозия в теле \r\nдамбы накопителя Обрушение \r\nоткоса дамбы \r\nнакопителя без \r\nзахвата пруда \r\nУсиление \r\nсуффозии в \r\nтеле дамбы \r\nнакопителя\r\nи/или \r\nНарушение общей \r\nфильтрационной \r\nпрочности тела \r\nдамбы накопителя\r\nНарушение общей \r\nфильтрационной \r\nпрочности \r\nоснования \r\nНарушение \r\nустойчивости откоса \r\nдамбы накопителя\r\nОбрушение \r\nоткоса без \r\nзахвата пруда \r\nПоверхность \r\nскольжения не входит \r\nв зону пруда \r\nили\r\n1 2 3 4\r\nисключительное или\r\nили\r\nи\r\nи\r\nи\r\nСуффозия в \r\nтеле дамбы \r\nнакопителя\r\nили", "[стр. 33]\n30\r\nисключительное или\r\nОсновное сочетание \r\nвоздействий \r\n1\r\nПроизводительность \r\nнасосной станции береговой \r\nили плавучей меньше \r\nнеобходимой\r\nПроизводительность насосной \r\nстанции береговой или ПН \r\nменьше необходимой при \r\nэкстремальных погодных явл.\r\nблокировка\r\nПервичный отказ насосной \r\nстанции\r\nОсобое сочетание \r\nи нагрузок \r\nисключительное или\r\nСбой электропитания Производительность \r\nнасосных меньше \r\nрасчетной\r\n5\r\nили и\r\nВетровое \r\nволнение и \r\nнагон волны \r\nКанала отвода \r\nручья не готов к \r\nиспользованию\r\nСверх расчетный \r\nпаводок \r\nЛивневые \r\nдожди \r\nТаяние снега \r\n2\r\nУровень воды в пруде находится на \r\nкритической отметке блокировка\r\nОтказ насосной станции\r\nили ….. и\r\nили и\r\nОтказ \r\nплавучей НС\r\nОтказ береговой \r\nнасосной￾или ….. и\r\nВторичный отказ насосной \r\nстанции\r\n6\r\nисключительное или\r\nОтказ одной из двух насосных \r\nстанций \r\nОтказ одной из двух насосных \r\nстанций из-за экстремальных \r\nпогодных явлений 1\r\n1 Особое сочетание \r\nвоздействий блокировка\r\n2\r\n2", "[стр. 34]\n31\r\nОбрушение откоса дамбы накопителя Осадка гребня дамбы ниже уровня воды \r\nили\r\n3\r\nОсадка гребня без \r\nразжижения материала \r\nгрунта\r\nУровень воды в \r\nнакопителе выше \r\nотметки гребня дамбы\r\nблокировка\r\nОсадка гребня \r\nдамбы \r\nисключительное или\r\nОсадка гребня при \r\nразжижении материала \r\nгрунта\r\nОсадка гребня\r\nблокировка Разжижение \r\nесть\r\nОсадка гребня\r\nРазжижение \r\nблокировка отсутствует\r\nКоэффициент устойчивости \r\nКs<1 без разжижения \r\nматериала /грунта\r\nПоверхность скольжения \r\nвходит в зону \r\nповерхности воды\r\nблокировка\r\nНарушение \r\nустойчивости откоса \r\nдамбы Кs<1\r\nисключительное или\r\nКоэффициент устойчивости \r\nКs<1 при разжижении \r\nматериала/грунта\r\nКs<1\r\nблокировка Разжижение \r\nесть\r\nКs<1\r\nРазжижение \r\nблокировка отсутствует", "[стр. 35]\n32\r\nРис 2.4 «Дерево отказов»\r\nОсадка гребня без \r\nразжижения грунта \r\nУровень воды в пруде выше \r\nотметки гребня дамбы \r\nнакопителя после ее осадки и\r\nОсадка гребня дамбы \r\nнакопителя\r\n4\r\nисключительное или\r\nОсадка гребня при \r\nразжижении грунта \r\n5\r\nили\r\nОтказ насосов \r\nплавучей насосной \r\nстанции \r\nОтказ насосов \r\nбереговой насосной \r\nстанции \r\n6\r\nисключительное или\r\nОшибка \r\nперсонала\r\nНасосы не готовы к \r\nиспользованию", "[стр. 36]\n33\r\n• вероятность реализации сценария №1 – обрушения низового откоса ограждающей \r\nдамбы при потере статической устойчивости сооружения – составляет \r\nР1 = 3,82*10-5\r\n1/год\r\n• вероятность реализации сценария №2 – разрушение ограждающей дамбы из-за поте￾ри фильтрационной прочности тела и/или основания – составляет Р2 = 8,4*10-5\r\n1/год;\r\n• вероятность реализации сценария №3 – разрушение ограждающей дамбы при пере￾ливе воды через ее гребень – составляет Р3 = 4,77*10-5\r\n1/год\r\n• вероятность реализации сценария №4 – местный размыв дамбы из-за аварии на рас￾пределительном пульповоде, проложенном по гребню дамбы – составляет \r\nР4 = 10-7\r\n1/год", "[стр. 37]\n34\r\nПриложение 3. Результаты расчетов параметров зон аварийного воздействия \r\nпри наиболее тяжелой и наиболее вероятной аварии ГТС\r\nВ случае прорыва напорного фронта хвостохранилища поток прорыва по естествен￾ным и искусственным водотокам будет двигаться по направлению понижения рельефа – по \r\nдолине реки Купец и далее по руслу реки Щучья в озеро Пясино.\r\nВодосборный бассейн р. Купец является частью бассейна р. Щучья. Верхняя его \r\nобласть занята промзоной г. Норильска и частично хвостохранилищем \"Лебяжье\".\r\nВ среднем течении, до выхода на территорию хвостохранилища, река течет в узкой \r\nврезанной долине. Русло шириной около 10-15 м и глубиной в межень 0,3-0,5 м, в \r\nосновном, валунно-галечниковое. Скорость течения в межень здесь составляет 0,5-1,0 м/с.\r\nНа участке смежном с хвостохранилищем река приобретает равнинный характер. \r\nДолина ее не выражена. Далее р. Купец протекает в неясно выраженной долине, \r\nобусловленной лишь орографией местности. Склоны долины умеренно-крутые, высотой 3-\r\n6 м. Ширина поймы реки изменяется в пределах 50-200 м (местами достигает 300 м), \r\nвысота ее 0,3-2,0 м над уровнем воды в межень. Поверхность поймы неровная, на ней \r\nвстречаются старицы, небольшие термокарстовые озера, бугры пучения. В период \r\nвесеннего половодья пойма р. Купец затапливается.\r\nДолина реки в створе 1 имеет трапецеидальную форму. Склоны очень крутые со \r\nсравнительно ровными поверхностями, подошва ясно обозначена, покрыты погибшим \r\nлесом, травяной покров отсутствует. Ширина долины по верху около 150 м. \r\nВ формировании долины наравне с эрозионной деятельностью реки принимает участие \r\nматериал, отложившийся в результате аварийных сбросов, происходивших в первые годы \r\nэксплуатации хвостохранилища «Лебяжье» в 1978-1979 годах, расположенного за правым \r\nсклоном долины. На склонах долины обнаружены по одной надпойменной террасе. \r\nПредположительно террасы сформировались в результате вышеуказанных сбросов \r\nматериала, после чего в переотложившемся грунте река промыла себе новое русло.\r\nПойма реки на данном участке узкая, шириной около 20 м. Пойма топкая, сложена \r\nгалькой и наилком техногенного происхождения. Присутствуют следы течения воды по \r\nпойме во время паводков, так же обнаружены следы карчехода, местами встречается \r\nбытовой и строительный мусор. Непосредственно у водотока пойма низкая, но плавно \r\nповышается к склонам долины, где её высота над урезом достигает 0,5 м.\r\nРусло реки извилистое, постоянно меняет своё положение в пределах поймы. Русло \r\nимеет корытообразную форму, распластанное, шириной в бровках до 4,5-6 м. Берега \r\nпологие, слабоустойчивые, покрыты наилком и галькой, растительность отсутствует. \r\nДно ровное, сложено галькой и обломочным материалом.\r\nРасчет проводится для наиболее тяжелой и наиболее вероятной аварии. Исходные \r\nданные для проведения расчетов, представлены в таблице\r\nТаблица 3.1 Исходные данные\r\nНаименование Ед. \r\nизм.\r\nДля наиболее \r\nтяжелой аварии\r\nДля наиболее \r\nвероятной аварии\r\nОбъем прудка млн. м3 15,0 8,4\r\nПлощадь прудка км2 4,46 3,3\r\nСредняя глубина прудка м 4,0 2,5\r\nШирина гребня дамбы м 10 10\r\nЗаложение верхового откоса м 5 100\r\nЗаложение низового откоса м 5 5\r\nВысота дамбы м 28 28\r\nНачальные размеры прорана м 10×0,5 1×1", "[стр. 38]\n35\r\nРезультаты проведенных расчетов для наиболее тяжелой аварии, представлены в \r\nтаблице\r\nТаблица 3.2 Результаты расчетов возможных последствий аварии для наиболее \r\nтяжелой аварии\r\nВ практике расчета возможного ущерба, время возможной аварии принято ограничи￾вать 2сутками. Принято считать, что за это время силами аварийно-восстановительных бри￾гад место аварийного разрушения будет локализовано и восстановлено. В этом случае из \r\nхвостохранилища вытечет 6,58 млн. м3 жидких отходов.\r\nРезультаты расчета параметров потока по трассе растекания, представлены в таблице\r\nРезультаты расчетов для наиболее вероятной аварии, представлены в таблице\r\nТаблица 3.3 Результаты расчетов возможных последствий аварии для наиболее \r\nвероятной аварии\r\nПри этом из хвостохранилища вытечет 2,1 млн. м3 жидких отходов.\r\nВ соответствии с полученными значениями параметров потока по створам, определим \r\nследующие границы зон разрушений:\r\nЗона катастрофических разрушений от расчетного створа 0 до 1.\r\nЗона сильных и средних разрушений от створа 1 до створа 2.\r\nЗона слабых разрушений от створа 2 до впадения в реку Щучья.\r\nРезультаты расчета параметров потока по трассе растекания, представлены в таблице\r\nТаблица 3.4. Результаты расчета трассы растекания волны от максимального расхода\r\nКонтролируемые параметры Значение\r\nМаксимальное значение полного расхода в проране, м3\r\n/с 42,8\r\nМаксимальная ширина прорана, м 31\r\nМаксимальная глубина прорана, м 4\r\nСкорость потока у подошвы откоса, м/с 1,5\r\nГлубина потока у подошвы дамбы, м 1,05\r\nВремя аварии, час ~100\r\nКонтролируемые параметры Значение\r\nМаксимальное значение полного расхода в проране, м3\r\n/с 13,6\r\nМаксимальная ширина прорана, м 16\r\nМаксимальная глубина прорана, м 3,3\r\nСкорость потока у подошвы откоса, м/с 1,0\r\nГлубина потока у подошвы дамбы, м 0,55\r\nВремя аварии, час ~100\r\n№ \r\nствора\r\nШирина, м Глубина, м Длина, м Скорость, м/с Время, ч\r\n0 16 1 0 2,1 52,1\r\n1 26 0,5 143 0,97 52,1\r\n2 42 0,3 960 0,8 52,3\r\n3 27 0,4 2000 0,9 54,1\r\n4 59 0,3 2600 0,8 58,1", "[стр. 39]\n36\r\nТаблица 3.5. Расчетные параметры существующего водотока (р. Купец)\r\n№ Параметр Ед. изм. Величина\r\n1 Максимальный расход весеннего половодья для р. \r\nКупец 1% обеспеченности м³/с 46,1\r\n2 Максимальный расход весеннего половодья для р. \r\nКупец 5% обеспеченности м³/с 35,9\r\n3 Расчетная скорость течения при прохождении \r\nмаксимального расхода 1% обеспеченности м/с 1,00\r\nВозможные направления потока прорыва: северное, западное и южное. С востока \r\nтретье поле хвостохранилища лебяжье примыкает к дамбе обвалования хвостохранилище \r\n«Лебяжье» (поле 1-2). В случае прорыва в южном и западном направлении весь поток \r\nпрорыва вдоль дамбы хвостохранилища по руслу обводного канала реки Купец уйдет в \r\nсеверном направлении. Учитывая параметры потока и высотные отметки местности, \r\nэлементы транспорта и другие объекты в зону затопления не попадают, кроме двух ниток \r\nмагистрального газопровода, проходящих через реку Купец между створами №№ 1 и 2. \r\nПри прорыве в северном направлении, в зону возможного затопления, также попадают 2 \r\nнитки магистрального газопровода, но при этом параметры потока прорыва будут больше, \r\nчем в случае прорыва в западном или южном направлениях. Весь поток прорыва пойдет по \r\nпойме реки Купец. Переходы газопроводов через реку Купец проектировались с учетом \r\nвозможного паводка 1% обеспеченности. Максимальный расчетный расход воды в проране \r\nпри наиболее тяжелом развитии аварийной ситуации меньше чем паводковый расход 1% \r\nобеспеченности на реке Купец, соответственно, можно принять, что в случае аварии, ущерб \r\nгазопроводу нанесен не будет.", "[стр. 40]\n37\r\nПриложение 4. Планы зон аварийного воздействия при наиболее тяжелой и \r\nнаиболее вероятной авариях ГТС в северном направлении", "[стр. 41]\n38\r\nПриложение 4.1. План зоны аварийного воздействия при прорыве в южном \r\nнаправлении", "[стр. 42]\n39\r\nПриложение 5. План ГТС", "[стр. 43]\n40\r\nПриложение 6. Типовое поперечное сечение по ГТС, аварии которых приняты к расчету вероятного вреда"]};
